il-tested'], $values, $url); } public static function renderInput(array $template, array $values, string $url = ''): array { $values += ['panel' => (string) config('app.name', 'Pterodactyl')]; $fill = fn (string $text) => self::fill($text, $values); $action = $fill((string) ($template['action'] ?? '')); return [ 'subject' => $fill((string) ($template['subject'] ?? '')), 'greeting' => $fill((string) ($template['greeting'] ?? '')), 'lines' => self::paragraphs($fill((string) ($template['body'] ?? ''))), 'action' => $url !== '' && $action !== '' ? ['label' => $action, 'url' => $url] : null, 'outro' => self::paragraphs($fill((string) ($template['outro'] ?? ''))), ]; } public static function apply(MailMessage $mail, string $key, array $values, string $url = ''): MailMessage { $content = self::render($key, $values, $url); $mail->viewData += ['dezerxEmail' => $key, 'dezerxValues' => $values + ['panel' => (string) config('app.name', 'Pterodactyl')]]; $mail->subject($content['subject']); if ($content['greeting'] !== '') { $mail->greeting($content['greeting']); } foreach ($content['lines'] as $line) { $mail->line($line); } if ($content['action'] !== null) { $mail->action($content['action']['label'], $content['action']['url']); } foreach ($content['outro'] as $line) { $mail->line($line); } return $mail; } public static function brand(): array { $logo = Appearance::logo(); $accent = OgImage::palette()['accent']; $image = ''; if (($logo['mode'] ?? 'text') !== 'text') { $image = (string) ($logo['imageLight'] ?: $logo['image']); } return [ 'name' => (string) ($logo['text'] ?: config('app.name', 'Pterodactyl')), 'logo' => $image === '' ? null : (str_starts_with($image, 'http') ? $image : url($image)), 'accent' => OgImage::hex(self::readable($accent)), 'url' => url('/'), ]; } private static function readable(array $rgb): array { $luminance = fn (array $c) => (0.2126 * $c[0] + 0.7152 * $c[1] + 0.0722 * $c[2]) / 255; while ($luminance($rgb) > 0.45) { $rgb = [(int) ($rgb[0] * 0.9), (int) ($rgb[1] * 0.9), (int) ($rgb[2] * 0.9)]; } return $rgb; } private static function fill(string $text, array $values): string { return preg_replace_callback( '/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/i', fn (array $found) => $values[strtolower($found[1])] ?? $found[0], $text, ) ?? $text; } private static function paragraphs(string $text): array { $out = []; foreach (preg_split("/\n\s*\n/", trim($text)) ?: [] as $block) { $block = trim($block); if ($block !== '') { $out[] = $block; } } return $out; } private static function merge(array $template, array $stored): array { foreach (array_keys(self::LIMITS) as $field) { if (isset($stored[$field]) && is_string($stored[$field])) { $template[$field] = self::clean($stored[$field], self::LIMITS[$field]); } } return $template; } private static function clean(mixed $value, int $limit): string { if (!is_string($value)) { return ''; } $value = str_replace("\r\n", "\n", $value); return mb_substr(trim($value), 0, $limit); } public const LAYOUT_SLOT = '@layout'; public const LAYOUT_LIMIT = 40000; public const HTML_LIMIT = 20000; public const LAYOUT_VARIABLES = [ 'content' => 'The message itself. Without this the layout has nothing in it.', 'subject' => 'The subject line, for the browser tab of a web view', 'brand_name' => 'Your panel name', 'brand_url' => 'A link back to the panel', 'brand_mark' => 'Your logo, or the panel name set in type if no logo is uploaded', 'brand_logo' => 'The logo address on its own, empty when none is uploaded', 'accent' => 'Your accent colour, darkened enough to read white text on', ]; public const BODY_VARIABLES = [ 'button' => 'The whole button, drawn for you. Empty when this message has no link.', 'action_text' => 'The words on the button', 'action_url' => 'Where the button goes. Generated by the panel; a reset link or a server address.', 'accent' => 'Your accent colour, darkened enough to read white text on', ]; public static function layoutDefault(): string { $path = resource_path('emails/layout.html'); return is_readable($path) ? (string) file_get_contents($path) : ''; } public static function layout(): string { $stored = Settings::get(self::SETTING_KEY) ?? []; $custom = is_string($stored[self::LAYOUT_SLOT] ?? null) ? trim($stored[self::LAYOUT_SLOT]) : ''; return $custom !== '' ? $custom : self::layoutDefault(); } public static function layoutIsCustom(): bool { $stored = Settings::get(self::SETTING_KEY) ?? []; return trim((string) ($stored[self::LAYOUT_SLOT] ?? '')) !== ''; } public static function saveLayout(string $html): void { $stored = Settings::get(self::SETTING_KEY) ?? []; $html = self::clean($html, self::LAYOUT_LIMIT); if ($html === '' || $html === trim(self::layoutDefault())) { unset($stored[self::LAYOUT_SLOT]); } else { $stored[self::LAYOUT_SLOT] = $html; } Settings::put(self::SETTING_KEY, $stored); } public static function resetLayout(): void { $stored = Settings::get(self::SETTING_KEY) ?? []; unset($stored[self::LAYOUT_SLOT]); Settings::put(self::SETTING_KEY, $stored); } public static function html(string $key): string { $stored = Settings::get(self::SETTING_KEY) ?? []; $value = $stored[$key]['html'] ?? null; return is_string($value) ? trim($value) : ''; } public static function saveHtml(string $key, string $html): void { if (!self::knows($key)) { return; } $stored = Settings::get(self::SETTING_KEY) ?? []; $row = is_array($stored[$key] ?? null) ? $stored[$key] : []; $html = self::clean($html, self::HTML_LIMIT); if ($html === '') { unset($row['html']); } else { $row['html'] = $html; } if ($row === []) { unset($stored[$key]); } else { $stored[$key] = $row; } Settings::put(self::SETTING_KEY, $stored); } public static function document(array $parts): string { $brand = self::brand(); $key = (string) ($parts['key'] ?? ''); $custom = array_key_exists('html', $parts) ? trim((string) $parts['html']) : ($key === '' ? '' : self::html($key)); $layout = trim((string) ($parts['layout'] ?? '')); $layout = $layout === '' ? self::layout() : $layout; $content = $custom === '' ? self::card($parts, $brand) : self::body($custom, $parts, $brand); return self::swap($layout, [ 'content' => $content, 'subject' => e((string) ($parts['subject'] ?? '') ?: $brand['name']), 'brand_name' => e($brand['name']), 'brand_url' => e($brand['url']), 'brand_logo' => e((string) ($brand['logo'] ?? '')), 'brand_mark' => self::mark($brand), 'accent' => e($brand['accent']), ]); } public static function body(string $html, array $parts, array $brand): string { $map = []; foreach ((array) ($parts['values'] ?? []) as $name => $value) { if (is_scalar($value)) { $map[strtolower((string) $name)] = e((string) $value); } } $label = (string) ($parts['actionText'] ?? ''); $url = (string) ($parts['actionUrl'] ?? ''); $map['action_text'] = e($label); $map['action_url'] = e($url); $map['accent'] = e($brand['accent']); $map['button'] = $label !== '' && $url !== '' ? self::button($label, $url, $brand['accent']) : ''; return self::swap($html, $map); } public static function card(array $parts, array $brand): string { $greeting = trim((string) ($parts['greeting'] ?? '')); $label = (string) ($parts['actionText'] ?? ''); $url = (string) ($parts['actionUrl'] ?? ''); $out = '<h1 style="margin: 0 0 16px; font-size: 20px; line-height: 1.3; font-weight: 600; color: #111827;">' . e($greeting === '' ? 'Hello' : $greeting) . '</h1>'; foreach ((array) ($parts['introLines'] ?? []) as $line) { $out .= self::para((string) $line); } if ($label !== '' && $url !== '') { $out .= self::button($label, $url, $brand['accent']); } foreach ((array) ($parts['outroLines'] ?? []) as $line) { $out .= self::para((string) $line); } if ($label !== '' && $url !== '') { $out .= '<p style="margin: 24px 0 0; padding-top: 20px; border-top: 1px solid #e5e7eb; font-size: 13px; line-height: 1.6; color: #6b7280;">' . 'If the button does not work, paste this address into your browser:<br>' . '<a href="' . e($url) . '" target="_blank" style="color: #6b7280; word-break: break-all;">' . e($url) . '</a>' . '</p>'; } return $out; } public static function seed(string $key): string { $template = self::template($key) ?? []; $greeting = trim((string) ($template['greeting'] ?? '')); $blocks = ['<h1 style="margin: 0 0 16px; font-size: 20px; line-height: 1.3; font-weight: 600; color: #111827;">' . e($greeting === '' ? 'Hello' : $greeting) . '</h1>']; foreach (self::paragraphs((string) ($template['body'] ?? '')) as $line) { $blocks[] = self::para($line); } if (trim((string) ($template['action'] ?? '')) !== '') { $blocks[] = '{{ button }}'; } foreach (self::paragraphs((string) ($template['outro'] ?? '')) as $line) { $blocks[] = self::para($line); } return implode("\n\n", $blocks); } private static function para(string $line): string { return '<p style="margin: 0 0 16px; font-size: 15px; line-height: 1.65; color: #4b5563;">' . nl2br(e($line)) . '</p>'; } private static function button(string $label, string $url, string $accent): string { return '<table cellpadding="0" cellspacing="0" role="presentation" style="margin: 24px 0;"><tr>' . '<td style="border-radius: 8px; background-color: ' . e($accent) . ';">' . '<a class="button" href="' . e($url) . '" target="_blank" style="display: inline-block; padding: 12px 22px;' . ' font-family: -apple-system, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; font-size: 15px;' . ' font-weight: 600; line-height: 1; color: #ffffff; text-decoration: none; border-radius: 8px;">' . e($label) . '</a></td></tr></table>'; } private static function mark(array $brand): string { if ($brand['logo'] === null) { return '<span style="font-family: -apple-system, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;' . ' font-size: 15px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #111827;">' . e($brand['name']) . '</span>'; } return '<img src="' . e($brand['logo']) . '" alt="' . e($brand['name']) . '" height="28" style="display: block; height: 28px; max-width: 220px; border: 0;">'; } private static function swap(string $template, array $map): string { return preg_replace_callback( '/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/i', fn (array $found) => $map[strtolower($found[1])] ?? $found[0], $template, ) ?? $template; } } 